'use client'

import { Button, ButtonSize, ButtonVariant, Icon, Input, InputHelperText, InputLabel } from '@graftcode/design-system'

import type { GatewayConfig } from '@/core/api'
import { useGatewaySettingsDialog } from '@/core/components/GatewaySelector/hooks/useGatewaySettingsDialog'
import type { GatewayUserSettings } from '@/core/utils/gateway-user-settings.interface'
import { VISION_SETTINGS_GATEWAY_TAB_TEST_IDS } from '@/core/vision-test-ids.const'

import { VISION_SETTINGS_COPY } from '../vision-settings.const'

import styles from './VisionSettingsGatewayTab.module.scss'

interface VisionSettingsGatewayTabProps {
  open: boolean
  gatewaySettings: GatewayUserSettings
  baseConfig: GatewayConfig
  applyGatewaySettings: (settings: GatewayUserSettings) => void
  resetGatewaySettings: () => void
  onRefetchGateway: () => Promise<unknown>
  onClose: () => void
}

export function VisionSettingsGatewayTab({
  open,
  gatewaySettings,
  baseConfig,
  applyGatewaySettings,
  resetGatewaySettings,
  onRefetchGateway,
  onClose,
}: VisionSettingsGatewayTabProps) {
  const copy = VISION_SETTINGS_COPY.gateway
  const dialog = useGatewaySettingsDialog({
    open,
    gatewaySettings,
    baseConfig,
    applyGatewaySettings,
    resetGatewaySettings,
    onRefetchGateway,
    onOpenChange: (next) => {
      if (!next) onClose()
    },
  })

  return (
    <div data-testid={VISION_SETTINGS_GATEWAY_TAB_TEST_IDS.root} className={styles.root}>
      <p className={styles.description}>{copy.description}</p>
      <div className={styles.fields}>
        <div className={styles.row}>
          <div className={styles.fieldBlock}>
            <InputLabel htmlFor="vision-settings-gateway-host">Host</InputLabel>
            <Input
              id="vision-settings-gateway-host"
              name="vision-settings-gateway-host"
              size="md"
              value={dialog.formValues.host ?? ''}
              onChange={(event) => dialog.updateField('host', event.target.value)}
            />
            {dialog.errors.host ? <InputHelperText variant="error">{dialog.errors.host}</InputHelperText> : null}
          </div>
          <div className={styles.fieldBlock}>
            <InputLabel htmlFor="vision-settings-gateway-http-port">HTTP port</InputLabel>
            <Input
              id="vision-settings-gateway-http-port"
              name="vision-settings-gateway-http-port"
              size="md"
              inputMode="numeric"
              value={dialog.formValues.httpPort ?? ''}
              onChange={(event) => dialog.updateField('httpPort', event.target.value)}
            />
            {dialog.errors.httpPort ? (
              <InputHelperText variant="error">{dialog.errors.httpPort}</InputHelperText>
            ) : null}
          </div>
        </div>
        <div className={styles.row}>
          <div className={styles.fieldBlock}>
            <InputLabel htmlFor="vision-settings-gateway-ws-port">WebSocket port</InputLabel>
            <Input
              id="vision-settings-gateway-ws-port"
              name="vision-settings-gateway-ws-port"
              size="md"
              inputMode="numeric"
              value={dialog.formValues.wsPort ?? ''}
              onChange={(event) => dialog.updateField('wsPort', event.target.value)}
              placeholder="Same as HTTP"
            />
            {dialog.errors.wsPort ? <InputHelperText variant="error">{dialog.errors.wsPort}</InputHelperText> : null}
          </div>
          <div className={styles.fieldBlock}>
            <InputLabel htmlFor="vision-settings-gateway-mcp-port">MCP port</InputLabel>
            <Input
              id="vision-settings-gateway-mcp-port"
              name="vision-settings-gateway-mcp-port"
              size="md"
              inputMode="numeric"
              value={dialog.formValues.mcpPort ?? ''}
              onChange={(event) => dialog.updateField('mcpPort', event.target.value)}
              placeholder="Same as HTTP"
            />
            {dialog.errors.mcpPort ? <InputHelperText variant="error">{dialog.errors.mcpPort}</InputHelperText> : null}
          </div>
        </div>
      </div>
      <footer className={styles.footer}>
        <div className={styles.footerReset}>
          <Button
            text={copy.reset}
            icon={Icon.ArrowCounterclockwiseRegular}
            variant={ButtonVariant.Outlined}
            size={ButtonSize.L}
            onClick={dialog.handleReset}
          />
        </div>
        <div className={styles.footerActions}>
          <Button
            text={copy.cancel}
            variant={ButtonVariant.Outlined}
            size={ButtonSize.L}
            onClick={dialog.handleDismiss}
          />
          <Button text={copy.save} size={ButtonSize.L} onClick={dialog.handleSave} />
        </div>
      </footer>
    </div>
  )
}
