'use client'

import { useMemo, useState } from 'react'

import { Button, ButtonSize, ButtonVariant, Icon, IconComponent } from '@graftcode/design-system'

import type { FilterStatistics } from '@/core/utils/filterConfig'
import { VISION_SETTINGS_FILTER_COMMAND_TEST_IDS } from '@/core/vision-test-ids.const'

import { VISION_SETTINGS_COPY } from '../vision-settings.const'

import styles from './FilterCommandFooter.module.scss'

interface FilterCommandFooterProps {
  statistics: FilterStatistics | null
  excludedCount: number
  ggCommand: string
  onResetSelection: () => void
  onCopyCommand: () => void
}

const COMMAND_PREVIEW_LENGTH = 96

export function FilterCommandFooter({
  statistics,
  excludedCount,
  ggCommand,
  onResetSelection,
  onCopyCommand,
}: FilterCommandFooterProps) {
  const [desktopExpanded, setDesktopExpanded] = useState(false)
  const [mobileCommandOpen, setMobileCommandOpen] = useState(false)
  const copy = VISION_SETTINGS_COPY.filters.command

  const displayCommand = useMemo(() => {
    if (desktopExpanded || ggCommand.length <= COMMAND_PREVIEW_LENGTH) {
      return ggCommand
    }
    return `${ggCommand.slice(0, COMMAND_PREVIEW_LENGTH)}...`
  }, [desktopExpanded, ggCommand])

  const showDesktopToggle = ggCommand.length > COMMAND_PREVIEW_LENGTH

  return (
    <footer data-testid={VISION_SETTINGS_FILTER_COMMAND_TEST_IDS.root} className={styles.footer}>
      <div className={styles.desktopPanel}>
        <div className={styles.footerRow}>
          <div className={styles.summary}>
            <p className={styles.commandTitle}>{copy.title}</p>
            <dl className={styles.stats}>
              <div>
                <dt>{statistics?.typesExposed ?? 0}</dt>
                <dd>{copy.types}</dd>
              </div>
              <div>
                <dt>{statistics?.methodsExposed ?? 0}</dt>
                <dd>{copy.methods}</dd>
              </div>
              <div>
                <dt>{statistics?.fieldsExposed ?? 0}</dt>
                <dd>{copy.fields}</dd>
              </div>
              <div>
                <dt>{excludedCount}</dt>
                <dd>{copy.excluded}</dd>
              </div>
            </dl>
          </div>
          <div className={styles.actions}>
            <Button
              text={copy.reset}
              icon={Icon.ArrowCounterclockwiseRegular}
              variant={ButtonVariant.Outlined}
              size={ButtonSize.L}
              className={styles.actionButton}
              onClick={onResetSelection}
            />
            <Button
              text={copy.copy}
              icon={Icon.CopyRegular}
              size={ButtonSize.L}
              className={styles.actionButton}
              onClick={onCopyCommand}
            />
          </div>
        </div>
        <div className={styles.commandBox}>
          <code className={styles.commandText}>{displayCommand}</code>
        </div>
        {showDesktopToggle ? (
          <button type="button" className={styles.expandButton} onClick={() => setDesktopExpanded((value) => !value)}>
            <span>{desktopExpanded ? copy.hideFull : copy.showFull}</span>
            <IconComponent icon={Icon.ChevronDownRegular} size={20} />
          </button>
        ) : null}
      </div>

      <div className={styles.mobilePanel}>
        <div className={styles.mobileStatsRow}>
          <dl className={styles.statsCompact}>
            <div>
              <dt>{statistics?.typesExposed ?? 0}</dt>
              <dd>{copy.types}</dd>
            </div>
            <div>
              <dt>{statistics?.methodsExposed ?? 0}</dt>
              <dd>{copy.methods}</dd>
            </div>
            <div>
              <dt>{statistics?.fieldsExposed ?? 0}</dt>
              <dd>{copy.fields}</dd>
            </div>
            <div>
              <dt>{excludedCount}</dt>
              <dd>{copy.excludedShort}</dd>
            </div>
          </dl>
          <button
            type="button"
            className={styles.mobileViewCommand}
            onClick={() => setMobileCommandOpen((value) => !value)}
          >
            <span>{mobileCommandOpen ? copy.hideCommand : copy.viewCommand}</span>
            <IconComponent icon={mobileCommandOpen ? Icon.ChevronUpRegular : Icon.ChevronDownRegular} size={20} />
          </button>
        </div>
        {mobileCommandOpen ? (
          <div className={styles.commandBox}>
            <code className={styles.commandText}>{ggCommand}</code>
          </div>
        ) : null}
      </div>

      <div className={styles.mobileCopyBar}>
        <Button
          text={copy.copy}
          icon={Icon.CopyRegular}
          size={ButtonSize.L}
          className={styles.mobileCopyButton}
          onClick={onCopyCommand}
        />
      </div>
    </footer>
  )
}
