'use client'

import { memo, useEffect } from 'react'

import { initUrlSync } from '@/core/stores'
import { CARD_WITH_PARAMS_TEST_IDS } from '@/core/vision-test-ids.const'

import { Card } from './Card'

function CardWithParamsComponent() {
  // Initialize URL synchronization on mount
  useEffect(() => {
    initUrlSync()
  }, [])

  return <Card data-testid={CARD_WITH_PARAMS_TEST_IDS.root} />
}

export const CardWithParams = memo(CardWithParamsComponent)
