'use client'

import { Checkbox, SearchBar, Select } from '@graftcode/design-system'

import { VISION_SETTINGS_CUSTOM_FILTERS_TEST_IDS } from '@/core/vision-test-ids.const'

import { CustomFilterRowBadge } from './CustomFilterRowBadge'

import styles from './CustomFiltersTable.module.scss'

export interface CustomFiltersTableRow {
  id: string
  name: string
  signature: string
  badgeLabel: string
  unsupported: boolean
}

interface CustomFiltersTableProps {
  columnLabel: string
  rows: CustomFiltersTableRow[]
  searchPlaceholder: string
  isRowChecked: (row: CustomFiltersTableRow) => boolean
  onRowCheckedChange: (row: CustomFiltersTableRow, checked: boolean) => void
}

export function CustomFiltersTable({
  columnLabel,
  rows,
  searchPlaceholder,
  isRowChecked,
  onRowCheckedChange,
}: CustomFiltersTableProps) {
  const visibleCheckedCount = rows.filter((row) => isRowChecked(row)).length
  const allVisibleChecked = rows.length > 0 && visibleCheckedCount === rows.length
  const someVisibleChecked = visibleCheckedCount > 0 && !allVisibleChecked

  const handleToggleAll = (checked: boolean) => {
    for (const row of rows) {
      onRowCheckedChange(row, checked)
    }
  }

  return (
    <div data-testid={VISION_SETTINGS_CUSTOM_FILTERS_TEST_IDS.table} className={styles.table}>
      <div className={styles.headerRow}>
        <div className={styles.headerCheckbox}>
          <Checkbox
            checked={allVisibleChecked ? true : someVisibleChecked ? 'indeterminate' : false}
            onChange={(value) => handleToggleAll(value === true)}
            aria-label={`Select all ${columnLabel.toLowerCase()} rows`}
          />
        </div>
        <p className={styles.headerLabel}>{columnLabel}</p>
      </div>

      <div className={styles.body}>
        {rows.length === 0 ? (
          <p className={styles.empty}>{searchPlaceholder}</p>
        ) : (
          rows.map((row) => (
            <label key={row.id} className={styles.row}>
              <Checkbox checked={isRowChecked(row)} onChange={(value) => onRowCheckedChange(row, value === true)} />
              <div className={styles.rowText}>
                <span className={styles.rowName}>{row.name}</span>
                <span className={row.unsupported ? styles.rowSignatureUnsupported : styles.rowSignature}>
                  {row.signature}
                </span>
              </div>
              <CustomFilterRowBadge badgeLabel={row.badgeLabel} unsupported={row.unsupported} />
            </label>
          ))
        )}
      </div>
    </div>
  )
}

export function CustomFiltersToolbar({
  typesLabel,
  methodsLabel,
  activeTab,
  onTabChange,
  searchQuery,
  onSearchChange,
  searchPlaceholder,
  showTypeFilter,
  typeFilterOptions,
  typeFilterValue,
  onTypeFilterChange,
  typeFilterPlaceholder,
}: {
  typesLabel: string
  methodsLabel: string
  activeTab: 'types' | 'methods'
  onTabChange: (tab: 'types' | 'methods') => void
  searchQuery: string
  onSearchChange: (value: string) => void
  searchPlaceholder: string
  showTypeFilter: boolean
  typeFilterOptions?: { value: string; label: string }[]
  typeFilterValue?: string
  onTypeFilterChange?: (value: string) => void
  typeFilterPlaceholder?: string
}) {
  return (
    <div className={styles.toolbar}>
      <div className={styles.segmented} role="tablist" aria-label="Custom filter categories">
        <button
          type="button"
          role="tab"
          aria-selected={activeTab === 'types'}
          className={activeTab === 'types' ? styles.segmentActive : styles.segment}
          onClick={() => onTabChange('types')}
        >
          {typesLabel}
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={activeTab === 'methods'}
          className={activeTab === 'methods' ? styles.segmentActive : styles.segment}
          onClick={() => onTabChange('methods')}
        >
          {methodsLabel}
        </button>
      </div>

      <div className={styles.toolbarActions}>
        {showTypeFilter && typeFilterOptions && onTypeFilterChange ? (
          <Select
            className={styles.typeFilter}
            size="md"
            value={typeFilterValue}
            placeholder={typeFilterPlaceholder}
            options={typeFilterOptions.map((option) => ({
              type: 'item',
              value: option.value,
              label: option.label,
            }))}
            onValueChange={onTypeFilterChange}
          />
        ) : null}
        <SearchBar
          className={styles.search}
          containerClassName={styles.searchContainer}
          size="sm"
          version="gray"
          placeholder={searchPlaceholder}
          value={searchQuery}
          onChange={(event) => onSearchChange(event.target.value)}
        />
      </div>
    </div>
  )
}
