'use client'

import { Button, ButtonSize, ButtonVariant, Icon, IconComponent } from '@graftcode/design-system'

import { formatNonGraftableCallablesMessage } from '@/core/utils/graftability/getUnsupportedMemberAlertModel'
import { UNSUPPORTED_TYPES_INSTALLATION_ALERT_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './UnsupportedTypesInstallationAlert.module.scss'

interface UnsupportedTypesInstallationAlertProps {
  nonGraftableCallableCount: number
  onConfigureFilters: () => void
}

export function UnsupportedTypesInstallationAlert({
  nonGraftableCallableCount,
  onConfigureFilters,
}: UnsupportedTypesInstallationAlertProps) {
  if (nonGraftableCallableCount <= 0) {
    return null
  }

  return (
    <div data-testid={UNSUPPORTED_TYPES_INSTALLATION_ALERT_TEST_IDS.root} className={styles.root}>
      <IconComponent icon={Icon.ErrorCircleFilled} size={16} className={styles.icon} aria-hidden />
      <p className={styles.message}>{formatNonGraftableCallablesMessage(nonGraftableCallableCount)}</p>
      <Button
        text="Configure filters"
        icon={Icon.FilterRegular}
        variant={ButtonVariant.Secondary}
        size={ButtonSize.S}
        onClick={onConfigureFilters}
        className={styles.action}
      />
    </div>
  )
}
