import type { Dispatch, SetStateAction } from 'react'

import type { MethodScope, VisionFilterMode } from '../types'

export type VisionFilterModeChangeSetters = {
  setGraftableMethodsOnly: Dispatch<SetStateAction<boolean>>
  setGraftableTypesOnly: Dispatch<SetStateAction<boolean>>
  setSelectedTypes: Dispatch<SetStateAction<string[]>>
  setTypePatternsText: Dispatch<SetStateAction<string>>
  setMethodScope: Dispatch<SetStateAction<MethodScope>>
  setSelectedMethodNames: Dispatch<SetStateAction<string[]>>
  setPerTypeMethods: Dispatch<SetStateAction<Record<string, string[]>>>
  setMethodPatternsText: Dispatch<SetStateAction<string>>
  setTargetType: Dispatch<SetStateAction<string>>
}

export function applyVisionFilterModeChange(
  mode: VisionFilterMode,
  allTypeFqns: string[],
  setters: VisionFilterModeChangeSetters
): void {
  switch (mode) {
    case 'none':
      setters.setGraftableMethodsOnly(false)
      setters.setGraftableTypesOnly(false)
      setters.setSelectedTypes(allTypeFqns)
      setters.setTypePatternsText('')
      setters.setMethodScope('all')
      setters.setSelectedMethodNames([])
      setters.setPerTypeMethods({})
      setters.setMethodPatternsText('')
      setters.setTargetType(allTypeFqns[0] ?? '')
      break
    case 'graftable-api':
      setters.setGraftableTypesOnly(true)
      setters.setGraftableMethodsOnly(true)
      break
    case 'graftable-types':
      setters.setGraftableMethodsOnly(false)
      setters.setGraftableTypesOnly(true)
      break
    case 'graftable-methods':
      setters.setGraftableTypesOnly(false)
      setters.setGraftableMethodsOnly(true)
      break
    case 'custom':
      setters.setGraftableMethodsOnly(false)
      setters.setGraftableTypesOnly(false)
      setters.setMethodScope('perType')
      break
    default:
      break
  }
}
