'use client'

import { useMemo, useState } from 'react'

import type { GraftFilterWizardData } from '@/core/components/GraftFilterWizard/types'
import type { LibraryData } from '@/core/types/library.type'
import { buildMethodGraftabilityIndex, type MethodGraftabilityIndex } from '@/core/utils/filterConfig'
import { VISION_SETTINGS_CUSTOM_FILTERS_TEST_IDS } from '@/core/vision-test-ids.const'

import {
  buildCustomFilterMethodRows,
  buildCustomFilterTypeRows,
  type CustomFilterMethodRow,
  type CustomFilterTypeRow,
} from '../utils/buildCustomFilterRows'
import { VISION_SETTINGS_COPY } from '../vision-settings.const'

import { CustomFiltersTable, CustomFiltersToolbar } from './CustomFiltersTable'

import styles from './CustomFiltersPanel.module.scss'

interface CustomFiltersPanelProps {
  wizard: GraftFilterWizardData
  libraryData?: LibraryData
}

function matchesSearch(query: string, name: string, signature: string): boolean {
  if (!query.trim()) return true
  const normalized = query.trim().toLowerCase()
  return name.toLowerCase().includes(normalized) || signature.toLowerCase().includes(normalized)
}

export function CustomFiltersPanel({ wizard, libraryData }: CustomFiltersPanelProps) {
  const [customTab, setCustomTab] = useState<'types' | 'methods'>('types')
  const [searchQuery, setSearchQuery] = useState('')
  const [typeFilter, setTypeFilter] = useState('all')

  const copy = VISION_SETTINGS_COPY.filters
  const statistics = wizard.preview?.statistics
  const typesTabLabel = `${copy.customSubTabs.types} (${statistics?.typesExposed ?? wizard.types.selectedTypes.length})`
  const methodsTabLabel = `${copy.customSubTabs.methods} (${statistics?.methodsExposed ?? 0})`

  const graftabilityIndex = useMemo<MethodGraftabilityIndex>(
    () => (libraryData ? buildMethodGraftabilityIndex(libraryData, wizard.constructorToken) : new Map()),
    [libraryData, wizard.constructorToken]
  )

  const typeRows = useMemo(
    () => buildCustomFilterTypeRows(wizard.types.availableTypes, libraryData),
    [libraryData, wizard.types.availableTypes]
  )

  const methodRows = useMemo(
    () => buildCustomFilterMethodRows(libraryData, wizard.constructorToken, graftabilityIndex),
    [graftabilityIndex, libraryData, wizard.constructorToken]
  )

  const typeFilterOptions = useMemo(
    () => [
      { value: 'all', label: copy.allTypesFilter },
      ...wizard.types.availableTypes.map((type) => ({ value: type.fqn, label: type.label })),
    ],
    [copy.allTypesFilter, wizard.types.availableTypes]
  )

  const filteredTypeRows = useMemo(
    () => typeRows.filter((row) => matchesSearch(searchQuery, row.name, row.signature)),
    [searchQuery, typeRows]
  )

  const filteredMethodRows = useMemo(
    () =>
      methodRows.filter((row) => {
        if (typeFilter !== 'all' && row.typeFqn !== typeFilter) return false
        return matchesSearch(searchQuery, row.name, row.signature)
      }),
    [methodRows, searchQuery, typeFilter]
  )

  const isTypeRowChecked = (row: CustomFilterTypeRow) => wizard.types.selectedTypes.includes(row.fqn)

  const handleTypeRowChange = (row: CustomFilterTypeRow, checked: boolean) => {
    wizard.types.onToggleType(row.fqn, checked)
  }

  const isMethodRowChecked = (row: CustomFilterMethodRow) =>
    wizard.methods.isMethodSelectedForType(row.typeFqn, row.memberName)

  const handleMethodRowChange = (row: CustomFilterMethodRow, checked: boolean) => {
    wizard.methods.onToggleMethodForType(row.typeFqn, row.memberName, checked)
  }

  const tableRows = customTab === 'types' ? filteredTypeRows : filteredMethodRows

  return (
    <div data-testid={VISION_SETTINGS_CUSTOM_FILTERS_TEST_IDS.root} className={styles.panel}>
      <p className={styles.panelTitle}>{copy.customPanelTitle}</p>

      <CustomFiltersToolbar
        typesLabel={typesTabLabel}
        methodsLabel={methodsTabLabel}
        activeTab={customTab}
        onTabChange={setCustomTab}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        searchPlaceholder={copy.searchPlaceholder}
        showTypeFilter={customTab === 'methods'}
        typeFilterOptions={typeFilterOptions}
        typeFilterValue={typeFilter}
        onTypeFilterChange={setTypeFilter}
        typeFilterPlaceholder={copy.allTypesFilter}
      />

      <CustomFiltersTable
        columnLabel={customTab === 'types' ? copy.columnType : copy.columnMethod}
        rows={tableRows}
        searchPlaceholder={copy.emptyResults}
        isRowChecked={(row) =>
          customTab === 'types'
            ? isTypeRowChecked(row as CustomFilterTypeRow)
            : isMethodRowChecked(row as CustomFilterMethodRow)
        }
        onRowCheckedChange={(row, checked) =>
          customTab === 'types'
            ? handleTypeRowChange(row as CustomFilterTypeRow, checked)
            : handleMethodRowChange(row as CustomFilterMethodRow, checked)
        }
      />
    </div>
  )
}
