'use client'

import { useEffect, useRef } from 'react'

import { Chip, ChipSize } from '@graftcode/design-system'

import type { VisionFilterMode } from '@/core/components/GraftFilterWizard/types'
import { VISION_SETTINGS_FILTER_MODE_TEST_IDS } from '@/core/vision-test-ids.const'

import { VISION_SETTINGS_COPY } from '../vision-settings.const'

import styles from './FilteringModeSection.module.scss'

interface FilteringModeSectionProps {
  filterMode: VisionFilterMode
  onFilterModeChange: (mode: VisionFilterMode) => void
}

export function FilteringModeSection({ filterMode, onFilterModeChange }: FilteringModeSectionProps) {
  const copy = VISION_SETTINGS_COPY.filters
  const chipsRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const container = chipsRef.current
    if (!container) {
      return
    }

    const activeChip = container.querySelector('.chip--active')
    if (activeChip instanceof HTMLElement) {
      activeChip.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' })
    }
  }, [filterMode])

  return (
    <section data-testid={VISION_SETTINGS_FILTER_MODE_TEST_IDS.root} className={styles.section}>
      <div className={styles.intro}>
        <h2 className={styles.title}>{copy.modeTitle}</h2>
        <p className={styles.description}>{copy.modeDescription}</p>
      </div>
      <div className={styles.chipsScroll}>
        <div ref={chipsRef} className={styles.chips}>
          {copy.modes.map((mode) => (
            <Chip
              key={mode.id}
              text={mode.label}
              size={ChipSize.L}
              active={filterMode === mode.id}
              onClick={() => onFilterModeChange(mode.id)}
            />
          ))}
        </div>
      </div>
      <p className={styles.modeHint}>{copy.modeDescriptions[filterMode]}</p>
    </section>
  )
}
