import { type Dispatch, type SetStateAction, useCallback } from 'react'

export type UseGraftFilterWizardTogglesParams = {
  targetType: string
  perTypeMethods: Record<string, string[]>
  setSelectedTypes: Dispatch<SetStateAction<string[]>>
  setSelectedMethodNames: Dispatch<SetStateAction<string[]>>
  setPerTypeMethods: Dispatch<SetStateAction<Record<string, string[]>>>
}

export function useGraftFilterWizardToggles({
  targetType,
  perTypeMethods,
  setSelectedTypes,
  setSelectedMethodNames,
  setPerTypeMethods,
}: UseGraftFilterWizardTogglesParams) {
  const toggleType = useCallback(
    (fqn: string, checked: boolean) => {
      setSelectedTypes((current) => {
        if (checked) return Array.from(new Set([...current, fqn]))
        return current.filter((value) => value !== fqn)
      })
    },
    [setSelectedTypes]
  )

  const toggleAllScopeMethod = useCallback(
    (name: string, checked: boolean) => {
      setSelectedMethodNames((current) => {
        if (checked) return Array.from(new Set([...current, name]))
        return current.filter((value) => value !== name)
      })
    },
    [setSelectedMethodNames]
  )

  const togglePerTypeMethod = useCallback(
    (name: string, checked: boolean) => {
      if (!targetType) return
      setPerTypeMethods((current) => {
        const existing = current[targetType] ?? []
        const next = checked ? Array.from(new Set([...existing, name])) : existing.filter((value) => value !== name)

        if (next.length === 0) {
          const { [targetType]: _removed, ...rest } = current
          return rest
        }

        return { ...current, [targetType]: next }
      })
    },
    [targetType, setPerTypeMethods]
  )

  const toggleMethodForType = useCallback(
    (typeFqn: string, name: string, checked: boolean) => {
      setPerTypeMethods((current) => {
        const existing = current[typeFqn] ?? []
        const next = checked ? Array.from(new Set([...existing, name])) : existing.filter((value) => value !== name)

        if (next.length === 0) {
          const { [typeFqn]: _removed, ...rest } = current
          return rest
        }

        return { ...current, [typeFqn]: next }
      })
    },
    [setPerTypeMethods]
  )

  const isMethodSelectedForType = useCallback(
    (typeFqn: string, name: string) => (perTypeMethods[typeFqn] ?? []).includes(name),
    [perTypeMethods]
  )

  return {
    toggleType,
    toggleAllScopeMethod,
    togglePerTypeMethod,
    toggleMethodForType,
    isMethodSelectedForType,
  }
}
