'use client'

import { type ComponentProps, type ReactNode, useCallback, useMemo, useState } from 'react'

import { InstallationCard, type Technology } from '@graftcode/design-system'

type InstallationCardWithPanelFooterProps = ComponentProps<typeof InstallationCard> & {
  panelFooter?: ReactNode
  onSettingsClick?: () => void
  headerLabel?: string
}

import { UnsupportedTypesInstallationAlert } from '@/core/components/UnsupportedTypesInstallationAlert'
import { VisionSettingsDialog } from '@/core/components/VisionSettingsDialog'
import { useLibraries } from '@/core/hooks'
import type { LibraryData } from '@/core/types/library.type'
import { countNonGraftableCallables, type LibraryGraftabilityReport } from '@/core/utils/graftability'
import { CARD_INSTALLATION_TEST_IDS } from '@/core/vision-test-ids.const'

import type { InstallationTab } from '../../types'

import styles from './CardInstallation.module.scss'

interface CardInstallationProps {
  installationCardKey: string
  technologies: Technology[]
  suggestedTechnologies: string[]
  selectedTechnology?: string
  tabs: InstallationTab[]
  libraryData?: LibraryData
  graftabilityReport?: LibraryGraftabilityReport | null
  onTechnologyChange: (technology: string) => void
  onConnectionStringGenerator: () => void
}

export function CardInstallation({
  installationCardKey,
  technologies,
  suggestedTechnologies,
  selectedTechnology,
  tabs,
  libraryData,
  graftabilityReport,
  onTechnologyChange,
  onConnectionStringGenerator,
}: CardInstallationProps) {
  const { refetch } = useLibraries()
  const [settingsOpen, setSettingsOpen] = useState(false)
  const openSettings = useCallback(() => setSettingsOpen(true), [])

  const nonGraftableCallableCount = useMemo(() => {
    if (!libraryData || graftabilityReport?.graftable) {
      return 0
    }

    return countNonGraftableCallables(libraryData)
  }, [graftabilityReport?.graftable, libraryData])

  const panelFooter = useMemo(() => {
    if (nonGraftableCallableCount <= 0) {
      return null
    }

    return (
      <UnsupportedTypesInstallationAlert
        nonGraftableCallableCount={nonGraftableCallableCount}
        onConfigureFilters={openSettings}
      />
    )
  }, [nonGraftableCallableCount, openSettings])

  const installationCardProps = {
    headerLabel: 'Setup',
    technologies,
    suggestedTechnologies,
    selectedTechnology,
    tabs,
    panelFooter,
    onTechnologyChange: (technology: string | undefined) => onTechnologyChange(technology ?? ''),
    onConnectionStringGenerator,
    onSettingsClick: openSettings,
  } satisfies InstallationCardWithPanelFooterProps

  return (
    <div data-testid={CARD_INSTALLATION_TEST_IDS.root} className={styles.container}>
      <InstallationCard
        key={installationCardKey}
        {...(installationCardProps as ComponentProps<typeof InstallationCard>)}
      />
      <VisionSettingsDialog
        open={settingsOpen}
        libraryData={libraryData}
        onOpenChange={setSettingsOpen}
        onRefetchGateway={refetch}
      />
    </div>
  )
}
