'use client'

import { useMemo, useState } from 'react'

import { Dialog, Heading, Tabs } from '@graftcode/design-system'

import { useGraftFilterWizard } from '@/core/components/GraftFilterWizard/hooks'
import type { VisionSettingsDialogProps } from '@/core/components/GraftFilterWizard/types'
import { useGatewayUserSettings } from '@/core/hooks/useGatewayUserSettings'
import { getGatewayConfig } from '@/core/utils/gateway'
import { VISION_SETTINGS_DIALOG_TEST_IDS } from '@/core/vision-test-ids.const'

import { CustomFiltersPanel } from './components/CustomFiltersPanel'
import { FilterCommandFooter } from './components/FilterCommandFooter'
import { FilteringModeSection } from './components/FilteringModeSection'
import { VisionSettingsGatewayTab } from './components/VisionSettingsGatewayTab'
import { VISION_SETTINGS_COPY } from './vision-settings.const'

import styles from './VisionSettingsDialog.module.scss'

export function VisionSettingsDialog({ open, libraryData, onOpenChange, onRefetchGateway }: VisionSettingsDialogProps) {
  const [activeTab, setActiveTab] = useState('filters')
  const wizard = useGraftFilterWizard({ open, libraryData, onOpenChange })
  const { host, port, isSecured } = getGatewayConfig()
  const { gatewaySettings, applyGatewaySettings, resetGatewaySettings } = useGatewayUserSettings()
  const baseConfig = useMemo(() => ({ host, port, isSecured }), [host, port, isSecured])

  const excludedCount = useMemo(() => {
    if (!libraryData || !wizard.preview?.statistics) return 0
    const totalTypes = Object.keys(libraryData.classes ?? {}).length
    return Math.max(0, totalTypes - wizard.preview.statistics.typesExposed)
  }, [libraryData, wizard.preview])

  const copy = VISION_SETTINGS_COPY

  const filtersContent = (
    <div className={styles.filtersTab}>
      <div className={styles.filtersScroll}>
        <FilteringModeSection filterMode={wizard.filterMode} onFilterModeChange={wizard.onFilterModeChange} />
        {wizard.filterMode === 'custom' ? <CustomFiltersPanel wizard={wizard} libraryData={libraryData} /> : null}
      </div>
      <FilterCommandFooter
        statistics={wizard.preview?.statistics ?? null}
        excludedCount={excludedCount}
        ggCommand={wizard.output.ggCommand}
        onResetSelection={wizard.onResetSelection}
        onCopyCommand={wizard.onCopyCommand}
      />
    </div>
  )

  const gatewayContent = (
    <VisionSettingsGatewayTab
      open={open && activeTab === 'gateway'}
      gatewaySettings={gatewaySettings}
      baseConfig={baseConfig}
      applyGatewaySettings={applyGatewaySettings}
      resetGatewaySettings={resetGatewaySettings}
      onRefetchGateway={onRefetchGateway}
      onClose={() => onOpenChange(false)}
    />
  )

  return (
    <Dialog
      open={open}
      noPadding
      showDismiss
      onOpenChange={onOpenChange}
      onDismiss={wizard.handleDismiss}
      maxWidth="60rem"
      className={styles.dialog}
      ariaLabelledBy="vision-settings-title"
    >
      <div data-testid={VISION_SETTINGS_DIALOG_TEST_IDS.root} className={styles.root}>
        <header className={styles.header}>
          <Heading type="h4" id="vision-settings-title">
            {copy.title}
          </Heading>
        </header>
        <Tabs
          className={styles.tabs}
          size="l"
          defaultTab={activeTab}
          items={[
            { id: 'filters', label: copy.tabs.filters, content: filtersContent },
            { id: 'gateway', label: copy.tabs.gateway, content: gatewayContent },
          ]}
          onValueChange={setActiveTab}
        />
      </div>
    </Dialog>
  )
}
