import { Runtime } from '@/core/enums/runtime.enum'
import type { ClassData, ConstructorData, MethodData } from '@/core/types/library.type'
import { renderTypeUsage } from '@/core/utils/mappers/formatTypeUsage/renderTypeUsage'
import { isConstructorTreeItem } from '@/core/utils/tree/isConstructorTreeItem'

function formatParameters(
  parameters: { name: string; type: string; typeUsage?: ConstructorData['parameters'][number]['typeUsage'] }[],
  runtimeName: Runtime
): string {
  return parameters
    .map((parameter) => {
      const typeLabel = parameter.typeUsage ? renderTypeUsage(parameter.typeUsage, runtimeName) : parameter.type
      return typeLabel ? `${typeLabel} ${parameter.name}` : parameter.name
    })
    .join(', ')
}

export function formatCustomFilterMemberSignature(
  classData: ClassData,
  member: MethodData | ConstructorData,
  _constructorToken: string,
  runtimeName: Runtime
): string {
  if (isConstructorTreeItem(member)) {
    const params = formatParameters(member.parameters, runtimeName)
    return params ? `${classData.name}(${params})` : `${classData.name}()`
  }

  const method = member as MethodData
  const returnType = method.returnTypeUsage
    ? renderTypeUsage(method.returnTypeUsage, runtimeName)
    : (method.returns ?? '')
  const params = formatParameters(method.parameters, runtimeName)
  const paramsSegment = params ? `(${params})` : '()'

  if (returnType) {
    return `${returnType} ${method.name}${paramsSegment}`
  }

  return `${classData.name} ${method.name}${paramsSegment}`
}
