import type { CodeState, CodeStore, FieldUsageTemplates } from './code.type'

const EMPTY_FIELD_USAGE: FieldUsageTemplates = { static: '', instance: '', global: '' }

export const selectSelectedSetupCommands = ({
  selectedTechnology = '',
  technologySetupCommands,
}: CodeState): Record<string, string> => technologySetupCommands[selectedTechnology] ?? {}

export const selectSelectedConfigurations = ({
  selectedTechnology = '',
  technologyConfigurations,
}: CodeState): Record<string, string> => technologyConfigurations[selectedTechnology] ?? {}

export const selectSelectedImportCode = ({ selectedTechnology = '', technologyImports }: CodeState): string =>
  technologyImports[selectedTechnology] ?? ''

export const selectSelectedInstanceCode = ({ selectedTechnology = '', technologyInstances }: CodeState): string =>
  technologyInstances[selectedTechnology] ?? ''

export const selectSelectedUsageCode = ({ selectedTechnology = '', technologyUsages }: CodeState): string =>
  technologyUsages[selectedTechnology] ?? ''

export const selectSelectedFieldUsageCode = ({
  selectedTechnology = '',
  technologyFieldUsages,
}: CodeState): FieldUsageTemplates => technologyFieldUsages[selectedTechnology] ?? EMPTY_FIELD_USAGE

export const selectSelectedVariableCode = ({ selectedTechnology = '', technologyVariables }: CodeState): string =>
  technologyVariables[selectedTechnology] ?? ''

export const selectSelectedTechnology = (state: CodeStore) => state.selectedTechnology

export const selectSuggestedTechnologies = (state: CodeStore) => state.suggestedTechnologies

export const selectTechnologies = (state: CodeStore) => state.technologies

export const selectTechnologySetupCommands = (state: CodeStore) => state.technologySetupCommands

export const selectTechnologyConfigurations = (state: CodeStore) => state.technologyConfigurations

export const selectTechnologyImports = (state: CodeStore) => state.technologyImports

export const selectTechnologyLibraryImports = (state: CodeStore) => state.technologyLibraryImports

export const selectCardCodeState = (state: CodeStore) => ({
  selectedTechnology: state.selectedTechnology,
  suggestedTechnologies: state.suggestedTechnologies,
  technologies: state.technologies,
  technologySetupCommands: state.technologySetupCommands,
  technologyConfigurations: state.technologyConfigurations,
  technologyImports: state.technologyImports,
  technologyLibraryImports: state.technologyLibraryImports,
  setSelectedTechnology: state.setSelectedTechnology,
})
