import type { MethodGraftabilityIndex } from '@/core/utils/filterConfig'

import { NO_GRAFTABLE_METHODS_SENTINEL } from '../graft-filter-wizard.const'
import { uniqueNonEmpty } from '../utils'

export function buildGraftableMethodsString(
  effectiveSelectedTypes: string[],
  graftabilityIndex: MethodGraftabilityIndex
): string {
  const patterns: string[] = []
  for (const fqn of effectiveSelectedTypes) {
    const memberMap = graftabilityIndex.get(fqn)
    if (!memberMap || memberMap.size === 0) continue

    const graftableMembers: string[] = []
    let fullyGraftable = true
    memberMap.forEach((graftable, member) => {
      if (graftable) graftableMembers.push(member)
      else fullyGraftable = false
    })

    if (fullyGraftable) {
      patterns.push(`${fqn}.*`)
    } else {
      graftableMembers.forEach((member) => patterns.push(`${fqn}.${member}`))
    }
  }

  const unique = uniqueNonEmpty(patterns)
  return unique.length > 0 ? unique.join(',') : NO_GRAFTABLE_METHODS_SENTINEL
}
