'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'

import type { ClassData } from '@/core/types/library.type'
import type { FilterableMethods, MethodGraftabilityIndex } from '@/core/utils/filterConfig'
import {
  buildMethodGraftabilityIndex,
  collectFilterableMethods,
  computeFilterStatistics,
  getConstructorToken,
  parseFilterPatterns,
} from '@/core/utils/filterConfig'
import { analyzeLibraryGraftability, buildGgFilterCommand } from '@/core/utils/graftability'

import type {
  AvailableType,
  GraftFilterWizardData,
  MethodScope,
  UseGraftFilterWizardParams,
  VisionFilterMode,
} from '../types'
import { classFqn, uniqueNonEmpty } from '../utils'

import { applyVisionFilterModeChange } from './applyVisionFilterModeChange'
import { buildGraftableMethodsString } from './buildGraftableMethodsString'
import { useGraftFilterWizardToggles } from './useGraftFilterWizardToggles'

/**
 * Holds the whole state machine of the filter wizard: type/method selection, graftability
 * shortcuts, derived filter strings, preview statistics and the generated GG command. The
 * component layer only renders the values returned here.
 */
export function useGraftFilterWizard({
  open,
  libraryData,
  onOpenChange,
}: UseGraftFilterWizardParams): GraftFilterWizardData {
  const report = useMemo(() => (libraryData ? analyzeLibraryGraftability(libraryData) : null), [libraryData])

  const constructorToken = useMemo(
    () => (libraryData ? getConstructorToken(libraryData.runtimeName) : 'constructor'),
    [libraryData]
  )

  const classesByFqn = useMemo(() => {
    const map = new Map<string, ClassData>()
    for (const classData of Object.values(libraryData?.classes ?? {})) {
      map.set(classFqn(classData), classData)
    }
    return map
  }, [libraryData])

  const graftabilityIndex = useMemo<MethodGraftabilityIndex>(
    () => (libraryData ? buildMethodGraftabilityIndex(libraryData, constructorToken) : new Map()),
    [libraryData, constructorToken]
  )

  const availableTypes = useMemo<AvailableType[]>(() => {
    if (!libraryData) return []

    return Object.values(libraryData.classes ?? {}).map((classData) => {
      const fqn = classFqn(classData)
      const memberMap = graftabilityIndex.get(fqn)
      let graftable = true
      memberMap?.forEach((isGraftable) => {
        if (!isGraftable) graftable = false
      })
      return {
        fqn,
        label: classData.name,
        graftable,
      }
    })
  }, [libraryData, graftabilityIndex])

  const allTypeFqns = useMemo(() => availableTypes.map((type) => type.fqn), [availableTypes])

  const graftableTypeFqns = useMemo(
    () => availableTypes.filter((type) => type.graftable).map((type) => type.fqn),
    [availableTypes]
  )

  const [selectedTypes, setSelectedTypes] = useState<string[]>([])
  const [typePatternsText, setTypePatternsText] = useState('')
  const [methodScope, setMethodScope] = useState<MethodScope>('all')
  const [selectedMethodNames, setSelectedMethodNames] = useState<string[]>([])
  const [perTypeMethods, setPerTypeMethods] = useState<Record<string, string[]>>({})
  const [methodPatternsText, setMethodPatternsText] = useState('')
  const [targetType, setTargetType] = useState<string>('')
  const [graftableMethodsOnly, setGraftableMethodsOnly] = useState(false)
  const [graftableTypesOnly, setGraftableTypesOnly] = useState(false)
  const [filterMode, setFilterMode] = useState<VisionFilterMode>('none')

  useEffect(() => {
    if (!open || !report) return
    setFilterMode('none')
    setSelectedTypes(allTypeFqns)
    setTypePatternsText('')
    setMethodScope('all')
    setSelectedMethodNames([])
    setPerTypeMethods({})
    setMethodPatternsText('')
    setTargetType(allTypeFqns[0] ?? '')
    setGraftableMethodsOnly(false)
    setGraftableTypesOnly(false)
  }, [open, report, allTypeFqns])

  const onFilterModeChange = useCallback(
    (mode: VisionFilterMode) => {
      setFilterMode(mode)
      applyVisionFilterModeChange(mode, allTypeFqns, {
        setGraftableMethodsOnly,
        setGraftableTypesOnly,
        setSelectedTypes,
        setTypePatternsText,
        setMethodScope,
        setSelectedMethodNames,
        setPerTypeMethods,
        setMethodPatternsText,
        setTargetType,
      })
    },
    [allTypeFqns]
  )

  const effectiveSelectedTypes = useMemo(() => {
    if (graftableMethodsOnly) return allTypeFqns
    if (graftableTypesOnly) return graftableTypeFqns
    return selectedTypes
  }, [graftableMethodsOnly, graftableTypesOnly, allTypeFqns, graftableTypeFqns, selectedTypes])

  useEffect(() => {
    if (effectiveSelectedTypes.length === 0) {
      setTargetType('')
      return
    }
    setTargetType((current) =>
      current && effectiveSelectedTypes.includes(current) ? current : (effectiveSelectedTypes[0] ?? '')
    )
  }, [effectiveSelectedTypes])

  const selectedTypeData = useMemo(
    () =>
      effectiveSelectedTypes.map((fqn) => classesByFqn.get(fqn)).filter((value): value is ClassData => Boolean(value)),
    [effectiveSelectedTypes, classesByFqn]
  )

  const allScopeMethods = useMemo(
    () => collectFilterableMethods(selectedTypeData, constructorToken),
    [selectedTypeData, constructorToken]
  )

  const perTypeScopeMethods = useMemo(() => {
    const classData = targetType ? classesByFqn.get(targetType) : undefined
    return collectFilterableMethods(classData ? [classData] : [], constructorToken)
  }, [targetType, classesByFqn, constructorToken])

  const typesString = useMemo(() => {
    if (graftableMethodsOnly) return uniqueNonEmpty(allTypeFqns).join(',')
    if (graftableTypesOnly) return uniqueNonEmpty(graftableTypeFqns).join(',')
    return uniqueNonEmpty([...selectedTypes, ...parseFilterPatterns(typePatternsText)]).join(',')
  }, [graftableMethodsOnly, graftableTypesOnly, allTypeFqns, graftableTypeFqns, selectedTypes, typePatternsText])

  const graftableMethodsString = useMemo(
    () => buildGraftableMethodsString(effectiveSelectedTypes, graftabilityIndex),
    [effectiveSelectedTypes, graftabilityIndex]
  )

  const methodsString = useMemo(() => {
    if (graftableMethodsOnly) return graftableMethodsString

    const generated =
      methodScope === 'all'
        ? selectedMethodNames
        : Object.entries(perTypeMethods).flatMap(([fqn, names]) => names.map((name) => `${fqn}.${name}`))

    return uniqueNonEmpty([...generated, ...parseFilterPatterns(methodPatternsText)]).join(',')
  }, [
    graftableMethodsOnly,
    graftableMethodsString,
    methodScope,
    selectedMethodNames,
    perTypeMethods,
    methodPatternsText,
  ])

  const isMemberGraftable = useCallback(
    (name: string): boolean => {
      if (methodScope === 'all') {
        for (const classData of selectedTypeData) {
          const memberMap = graftabilityIndex.get(classFqn(classData))
          if (memberMap?.has(name) && memberMap.get(name) === false) return false
        }
        return true
      }

      const memberMap = targetType ? graftabilityIndex.get(targetType) : undefined
      return memberMap?.get(name) ?? true
    },
    [methodScope, selectedTypeData, graftabilityIndex, targetType]
  )

  const statistics = useMemo(
    () => (libraryData ? computeFilterStatistics(libraryData, typesString, methodsString) : null),
    [libraryData, typesString, methodsString]
  )

  const ggCommand = useMemo(
    () =>
      buildGgFilterCommand({
        modulePath: report?.moduleFullName ?? './your-module.jar',
        types: parseFilterPatterns(typesString),
        methods: parseFilterPatterns(methodsString),
      }),
    [report, typesString, methodsString]
  )

  const configJson = useMemo(
    () => JSON.stringify({ types: typesString, methods: methodsString }, null, 2),
    [typesString, methodsString]
  )

  const { toggleType, toggleAllScopeMethod, togglePerTypeMethod, toggleMethodForType, isMethodSelectedForType } =
    useGraftFilterWizardToggles({
      targetType,
      perTypeMethods,
      setSelectedTypes,
      setSelectedMethodNames,
      setPerTypeMethods,
    })

  const handleDismiss = useCallback(() => onOpenChange(false), [onOpenChange])

  const onCopyCommand = useCallback(() => {
    void navigator.clipboard.writeText(ggCommand)
  }, [ggCommand])

  const onResetSelection = useCallback(() => onFilterModeChange('none'), [onFilterModeChange])

  const activeMethods: FilterableMethods = methodScope === 'all' ? allScopeMethods : perTypeScopeMethods
  const targetMethodSelection = perTypeMethods[targetType] ?? []

  return {
    report,
    constructorToken,
    filterMode,
    onFilterModeChange,
    onResetSelection,
    onCopyCommand,
    quickOptions: {
      graftableTypesOnly,
      graftableMethodsOnly,
      onGraftableTypesOnlyChange: setGraftableTypesOnly,
      onGraftableMethodsOnlyChange: setGraftableMethodsOnly,
    },
    types: {
      availableTypes,
      selectedTypes,
      graftableMethodsOnly,
      graftableTypesOnly,
      typePatternsText,
      onToggleType: toggleType,
      onTypePatternsChange: setTypePatternsText,
    },
    methods: {
      methodScope,
      graftableMethodsOnly,
      effectiveSelectedTypes,
      classesByFqn,
      perTypeMethods,
      targetType,
      activeMethods,
      constructorToken,
      selectedMethodNames,
      targetMethodSelection,
      methodPatternsText,
      isMemberGraftable,
      onMethodScopeChange: setMethodScope,
      onTargetTypeChange: setTargetType,
      onToggleAllScopeMethod: toggleAllScopeMethod,
      onTogglePerTypeMethod: togglePerTypeMethod,
      onToggleMethodForType: toggleMethodForType,
      isMethodSelectedForType,
      onMethodPatternsChange: setMethodPatternsText,
    },
    preview: statistics ? { statistics } : null,
    output: { configJson, ggCommand },
    handleDismiss,
  }
}
