import type { AvailableType } from '@/core/components/GraftFilterWizard/types'
import { classFqn } from '@/core/components/GraftFilterWizard/utils'
import { getBadgeLabel } from '@/core/hooks/useCardNavigation/utils/getBadgeLabel'
import { getFieldBadgeLabel } from '@/core/hooks/useCardNavigation/utils/getFieldBadgeLabel'
import type { ClassData, LibraryData } from '@/core/types/library.type'
import type { MethodGraftabilityIndex } from '@/core/utils/filterConfig'

import { formatCustomFilterMemberSignature } from './formatCustomFilterMemberSignature'

export interface CustomFilterTypeRow {
  id: string
  fqn: string
  name: string
  signature: string
  badgeLabel: string
  unsupported: boolean
  kind: 'class' | 'field'
}

export interface CustomFilterMethodRow {
  id: string
  typeFqn: string
  memberName: string
  name: string
  signature: string
  badgeLabel: string
  unsupported: boolean
}

function collectClasses(classes: Record<string, ClassData> | undefined): ClassData[] {
  if (!classes) return []
  const result: ClassData[] = []
  for (const classData of Object.values(classes)) {
    result.push(classData)
    if (classData.children) {
      result.push(...collectClasses(classData.children))
    }
  }
  return result
}

function isMemberGraftable(index: MethodGraftabilityIndex, typeFqn: string, memberName: string): boolean {
  return index.get(typeFqn)?.get(memberName) ?? true
}

export function buildCustomFilterTypeRows(
  availableTypes: AvailableType[],
  libraryData: LibraryData | undefined
): CustomFilterTypeRow[] {
  const rows: CustomFilterTypeRow[] = availableTypes.map((type) => ({
    id: `class:${type.fqn}`,
    fqn: type.fqn,
    name: type.label,
    signature: type.fqn,
    badgeLabel: 'Class',
    unsupported: !type.graftable,
    kind: 'class',
  }))

  for (const classData of collectClasses(libraryData?.classes)) {
    const typeFqn = classFqn(classData)
    for (const field of Object.values(classData.fields ?? {})) {
      rows.push({
        id: `field:${typeFqn}:${field.name}`,
        fqn: typeFqn,
        name: field.name,
        signature: `${classData.name} ${field.name}`,
        badgeLabel: getFieldBadgeLabel(field.type) ?? 'Field',
        unsupported: false,
        kind: 'field',
      })
    }
  }

  return rows.sort((a, b) => a.name.localeCompare(b.name) || a.signature.localeCompare(b.signature))
}

export function buildCustomFilterMethodRows(
  libraryData: LibraryData | undefined,
  constructorToken: string,
  graftabilityIndex: MethodGraftabilityIndex
): CustomFilterMethodRow[] {
  if (!libraryData) return []

  const rows: CustomFilterMethodRow[] = []
  const classes = collectClasses(libraryData.classes)

  for (const classData of classes) {
    const typeFqn = classFqn(classData)

    for (const constructor of Object.values(classData.constructors ?? {})) {
      const memberName = constructorToken
      rows.push({
        id: `${typeFqn}:${memberName}:${constructor.name}`,
        typeFqn,
        memberName,
        name: classData.name,
        signature: formatCustomFilterMemberSignature(classData, constructor, constructorToken, libraryData.runtimeName),
        badgeLabel: getBadgeLabel(constructor.type) ?? 'Constructor',
        unsupported: !isMemberGraftable(graftabilityIndex, typeFqn, memberName),
      })
    }

    for (const method of Object.values(classData.methods ?? {})) {
      rows.push({
        id: `${typeFqn}:${method.name}`,
        typeFqn,
        memberName: method.name,
        name: method.name,
        signature: formatCustomFilterMemberSignature(classData, method, constructorToken, libraryData.runtimeName),
        badgeLabel: getBadgeLabel(method.type) ?? 'Method',
        unsupported: !isMemberGraftable(graftabilityIndex, typeFqn, method.name),
      })
    }
  }

  return rows.sort((a, b) => a.name.localeCompare(b.name) || a.typeFqn.localeCompare(b.typeFqn))
}
