import { PropertiesTag } from '@graftcode/design-system'

import { VisionNotSupportedTag } from '@/core/components/VisionNotSupportedTag'
import { getBadgeType } from '@/core/utils/getBadgeType'
import { getPropertiesTagVariant } from '@/core/utils/getPropertiesTagVariant'

interface CustomFilterRowBadgeProps {
  badgeLabel: string
  unsupported: boolean
}

export function CustomFilterRowBadge({ badgeLabel, unsupported }: CustomFilterRowBadgeProps) {
  if (unsupported) {
    return <VisionNotSupportedTag />
  }

  return (
    <PropertiesTag variant={getPropertiesTagVariant(getBadgeType(badgeLabel))} withoutIcon>
      {badgeLabel}
    </PropertiesTag>
  )
}
